Adds a TextFragment paragraph to a new page, saves the document to memory, reloads it from the saved bytes and uses TextAbsorber to extract the page's text, checking that the extracted text contains the fragment that was written.

Example:
// Authored example: add a text fragment to a new page and extract it back with TextAbsorber
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import org.aspose.pdf.Document;
import org.aspose.pdf.Page;
import org.aspose.pdf.text.TextFragment;
import org.aspose.pdf.text.TextAbsorber;

public class TextFragmentRoundtripExample {
    public static void main(String[] args) throws Exception {
        Document document = new Document();
        Page page = document.getPages().add();
        page.getParagraphs().add(new TextFragment("Quarterly report ready"));

        ByteArrayOutputStream savedBytes = new ByteArrayOutputStream();
        document.save(savedBytes);

        Document reloaded = new Document(new ByteArrayInputStream(savedBytes.toByteArray()));
        TextAbsorber absorber = new TextAbsorber();
        reloaded.getPages().get(1).accept(absorber);
        String extracted = absorber.getText();

        System.out.println("extracted text: " + extracted);
        if (!extracted.contains("Quarterly report ready")) {
            throw new AssertionError("expected extracted text to contain the fragment we wrote");
        }
    }
}
