Adds a text fragment to a new page, renders that page to an in-memory PNG raster with PngDevice at a fixed Resolution, and checks that the produced bytes carry the real PNG signature.

Example:
// Authored example: render a PDF page to a PNG raster image with PngDevice and check its byte signature
import java.io.ByteArrayOutputStream;
import org.aspose.pdf.Document;
import org.aspose.pdf.Page;
import org.aspose.pdf.text.TextFragment;
import org.aspose.pdf.devices.PngDevice;
import org.aspose.pdf.devices.Resolution;

public class PngRenderExample {
    public static void main(String[] args) throws Exception {
        Document document = new Document();
        Page page = document.getPages().add();
        page.getParagraphs().add(new TextFragment("Render me to PNG"));

        PngDevice device = new PngDevice(new Resolution(150));
        ByteArrayOutputStream pngBytes = new ByteArrayOutputStream();
        device.process(page, pngBytes);
        byte[] rendered = pngBytes.toByteArray();

        System.out.println("PNG byte count: " + rendered.length);
        boolean isPngSignature = rendered.length > 8
                && (rendered[0] & 0xFF) == 0x89
                && rendered[1] == 'P' && rendered[2] == 'N' && rendered[3] == 'G';
        if (!isPngSignature) {
            throw new AssertionError("expected the rendered bytes to start with the PNG signature");
        }
    }
}
